function UIActionBossCollectionBossPopupDialog:OnBtnEntryAnnihilation()
    local vo = ActionUtils.GetRegionSecondaryMapVo(self._pointId)

    CS.Engine.Lib.KCookie.Set("UIActionSecondMapDialogtargetPointId", ActionUtils.GetBossPointId(self._mapId))
    UIModule.CloseDialog(self.controller)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionSecondMapDialog, parameters = {id = vo.regionBelong, pointId = self._pointId}}, {
        {id = Constants.UITypeIds.UIActionBossCollectionDialog }
    }) 
