function UIActionBossCollectionBossPopupDialog:InitData()
    local vo = ActionUtils.GetRegionSecondaryMapVo(self._pointId)
    self._mapId = vo.regionBelong
end

function UIActionBossCollectionBossPopupDialog:FillSelf()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    local vo = ActionUtils.GetRegionSecondaryMapVo(self._pointId)
    self._mapId = vo.regionBelong

    local mapVo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    CfUtils.FillImage(self.ImgBg, mapVo.OverviewBanner)

    local data = ActionUtils.GetAnnihilationInfo(self._mapId)
    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.FillText(self.TxtNumber, localize("_num_<size=50>%</size>", {_num_ = checkInt(checkNumber(data.progress) * 100)}))
    CfUtils.FillText(self.TxtDesc, vo.label)

    self._allRewardId = checkTable(CfUtils.Split(vo.reward))
    if self._isInitLoopList then
        GameUtils.ReloadData(self.ScrollView, table.count(self._allRewardId))
    else
        self.ScrollView:InitListView(table.count(self._allRewardId), Bind(self, self.OnRefreshIndex))
        self._isInitLoopList = true
    end


    local isOpen = ActionUtils.IsOpenAnnihilation(self._mapId)
    --CfUtils.SetActive(self.DestoryGroup, isOpen)
    --CfUtils.SetActive(self.FontStyleButton, not isOpen)

    if isOpen then
        local vo = ActionUtils.GetRegionAnnihilationTypeVo(data.bossTypeId)
        if vo then
            CfUtils.FillImage(self.ImgMonster, vo.bossPortrait)
            CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(checkNumber(data.remainTime)))
        end
        CfUtils.FillText(self.TxtNumber, localize("_num_<size=50>%</size>", {_num_ = 100}))
        self:StartTimeDown()
    end
end

function UIActionBossCollectionBossPopupDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local id = self._allRewardId[index + 1]

    local go = cell.gameObject
    CfUtils.RefeshGoodGo2(go.transform:Find("GoodNode"), id, nil, nil, nil, function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
    end)

    return cell
end

function UIActionBossCollectionBossPopupDialog:StartTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local data = ActionUtils.GetAnnihilationInfo(self._mapId)
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(checkNumber(data.remainTime)))
    end, CountDownTime, false, true)
end

function UIActionBossCollectionBossPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._pointId = checkNumber(argument.id)  

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIActionBossCollectionBossPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

